{"path": "/tmp/sv-e55b73411f0f4f04955c00e74cc491bd/Components/Pages/Chat/ChatPage.razor", "file_text": "@page "/chat"
@namespace sv_e55b73411f0f4f04955c00e74cc491bd.Components.Pages.Chat
@using sv_e55b73411f0f4f04955c00e74cc491bd.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(_threadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="_channels"
                    SelectedChannelId="_selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea CurrentChannel="_currentChannel"
                 Messages="_messages"
                 ThreadReplyCounts="_threadReplyCounts"
                 IsLoadingMore="_isLoadingMore"
                 OnLoadMore="LoadOlderMessages"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage" />

    @if (_threadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<Message> _threadReplies = [];
    private Dictionary<int, int> _threadReplyCounts = new();
    private Channel? _currentChannel;
    private Message? _threadRootMessage;
    private int _selectedChannelId;
    private bool _threadOpen;
    private bool _isLoadingMore;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        _currentChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
        await ChatService.MarkChannelReadAsync(channelId);
        ComputeThreadReplyCounts();
    }

    private async Task LoadOlderMessages()
    {
        if (_isLoadingMore || _currentChannel is null) return;
        _isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_currentChannel.Id, _messages.Count, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            ComputeThreadReplyCounts();
        }
        _isLoadingMore = false;
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        if (_currentChannel is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_currentChannel.Id, 0, _messages.Count);
        }
    }

    private async Task SendMessage(string content)
    {
        if (_currentChannel is null) return;
        var message = await ChatService.SendMessageAsync(_currentChannel.Id, content, null);
        _messages.Add(message);
    }

    private async Task SendThreadReply(string content)
    {
        if (_currentChannel is null || _threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_currentChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update reply count
        _threadReplyCounts[_threadRootMessage.Id] =
            _threadReplyCounts.GetValueOrDefault(_threadRootMessage.Id) + 1;
    }

    private void ComputeThreadReplyCounts()
    {
        _threadReplyCounts = _messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());
    }
}
"}

