toolArgs.file_text:
.chat-layout {
    display: grid;
    grid-template-columns: 20% 1fr;
    height: 100vh;
    overflow: hidden;
}

.chat-layout.thread-open {
    grid-template-columns: 20% 1fr 25%;
}

/* Sidebar */
::deep .channel-sidebar {
    background: #2b2d31;
    color: #f2f3f5;
    padding: 1rem 0;
    overflow-y: auto;
    border-right: 1px solid #1e1f22;
}

::deep .sidebar-title {
    padding: 0 1rem;
    margin: 0 0 0.75rem;
    font-size: 0.875rem;
    text-transform: uppercase;
    color: #949ba4;
    letter-spacing: 0.02em;
}

::deep .channel-list {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

::deep .channel-item {
    padding: 0.5rem 1rem;
    cursor: pointer;
    border-radius: 4px;
    margin: 0 0.5rem;
    position: relative;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #35373c;
}

::deep .channel-item.active {
    background: #404249;
}

::deep .channel-name {
    font-weight: 500;
    font-size: 0.9375rem;
    color: #f2f3f5;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #949ba4;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    position: absolute;
    right: 0.75rem;
    top: 50%;
    transform: translateY(-50%);
    background: #f23f43;
    color: white;
    font-size: 0.6875rem;
    font-weight: 700;
    padding: 0.125rem 0.375rem;
    border-radius: 9999px;
    min-width: 1rem;
    text-align: center;
}

/* Message Area */
::deep .message-area {
    display: flex;
    flex-direction: column;
    background: #313338;
    color: #dbdee1;
    overflow: hidden;
}

::deep .message-area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1rem;
    color: #f2f3f5;
}

::deep .message-area-header p {
    margin: 0.25rem 0 0;
    font-size: 0.75rem;
    color: #949ba4;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

::deep .loading-indicator {
    text-align: center;
    padding: 0.5rem;
    color: #949ba4;
    font-size: 0.8125rem;
}

::deep .no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #949ba4;
}

/* Message Bubble */
::deep .message-bubble {
    position: relative;
    padding: 0.375rem 0.75rem;
    border-radius: 4px;
    transition: background 0.1s;
}

::deep .message-bubble:hover {
    background: #2e3035;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

::deep .message-author {
    font-weight: 600;
    font-size: 0.875rem;
    color: #f2f3f5;
}

::deep .message-time {
    font-size: 0.6875rem;
    color: #949ba4;
}

::deep .message-content {
    font-size: 0.9375rem;
    line-height: 1.375;
    margin-top: 0.125rem;
    word-break: break-word;
}

::deep .reactions-row {
    display: flex;
    gap: 0.25rem;
    margin-top: 0.375rem;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.125rem 0.375rem;
    font-size: 0.8125rem;
    cursor: pointer;
    color: #dbdee1;
    transition: background 0.1s;
}

::deep .reaction-badge:hover {
    background: #3f4147;
    border-color: #5865f2;
}

::deep .thread-link {
    background: none;
    border: none;
    color: #00a8fc;
    font-size: 0.75rem;
    cursor: pointer;
    padding: 0.25rem 0;
    font-weight: 500;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 2px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.125rem;
}

::deep .action-btn {
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.25rem 0.375rem;
    border-radius: 3px;
    font-size: 0.875rem;
    transition: background 0.1s;
}

::deep .action-btn:hover {
    background: #3f4147;
}

::deep .emoji-picker {
    position: absolute;
    top: -2.5rem;
    right: 0.5rem;
    display: flex;
    gap: 2px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 6px;
    padding: 0.25rem;
    z-index: 10;
}

::deep .emoji-option {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1.125rem;
    padding: 0.25rem;
    border-radius: 3px;
    transition: background 0.1s;
}

::deep .emoji-option:hover {
    background: #3f4147;
}

/* Message Input */
::deep .message-input {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border-top: 1px solid #1e1f22;
    flex-shrink: 0;
}

::deep .message-input textarea {
    flex: 1;
    resize: none;
    background: #383a40;
    border: none;
    border-radius: 6px;
    padding: 0.625rem 0.75rem;
    color: #dbdee1;
    font-size: 0.875rem;
    font-family: inherit;
    outline: none;
}

::deep .message-input textarea::placeholder {
    color: #6d6f78;
}

::deep .send-btn {
    background: #5865f2;
    color: white;
    border: none;
    border-radius: 6px;
    padding: 0.5rem 1rem;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
    align-self: flex-end;
    transition: background 0.15s;
}

::deep .send-btn:hover:not(:disabled) {
    background: #4752c4;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
::deep .thread-panel {
    display: flex;
    flex-direction: column;
    background: #2b2d31;
    border-left: 1px solid #1e1f22;
    color: #dbdee1;
    overflow: hidden;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

::deep .thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #f2f3f5;
}

::deep .close-btn {
    background: none;
    border: none;
    color: #949ba4;
    font-size: 1.25rem;
    cursor: pointer;
    padding: 0.25rem 0.5rem;
    border-radius: 3px;
    transition: background 0.1s, color 0.1s;
}

::deep .close-btn:hover {
    background: #3f4147;
    color: #f2f3f5;
}

::deep .thread-root-message {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #1e1f22;
    background: #232428;
    flex-shrink: 0;
}

::deep .thread-root-message .message-author {
    font-size: 0.8125rem;
}

::deep .thread-root-message .message-content {
    font-size: 0.8125rem;
    color: #949ba4;
    margin-top: 0.25rem;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

::deep .thread-reply {
    padding: 0.375rem 0;
}

::deep .thread-reply .message-content {
    font-size: 0.875rem;
}

